        ["用你嘅 Claude、ChatGPT、Gemini 或者免費本地 AI 問嘢、寫程式、語音對話。"] = new[] { "使用你的 Claude、ChatGPT、Gemini 或免費本地 AI 問答、編寫程式及語音對話。", "使用你的 Claude、ChatGPT、Gemini 或免费本地 AI 问答、编写程序及语音对话。", "Ask questions, write code and chat by voice with your Claude, ChatGPT, Gemini or a free local AI." },
